package com.franco.desco.adapter.in.web.fieldtrip;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.fieldtrip.*;import com.franco.desco.application.fieldtrip.port.in.FieldTripUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController@RequestMapping("/api/v1/salidas-campo")@Tag(name="Salidas de campo",description="Programación, participantes, recursos y cierre de salidas de campo.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class FieldTripController{private final FieldTripUseCase u;private final FieldTripWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public FieldTripController(FieldTripUseCase u,FieldTripWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_LISTAR')")@Operation(operationId="salidasListar",summary="Listar salidas de campo")public ResponseEntity<ApiResponse<PageResponse<FieldTripResponses.Summary>>>list(@RequestParam(required=false)String estadoProceso,@RequestParam(required=false)Integer motivoSalidaId,@RequestParam(required=false)Instant fechaDesde,@RequestParam(required=false)Instant fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(200)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,estadoProceso,motivoSalidaId,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_VER')")@Operation(operationId="salidasVer",summary="Ver detalle completo de una salida")public ResponseEntity<ApiResponse<FieldTripResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new FieldTripCommands.GetTrip(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_CREAR')")@Operation(operationId="salidasProgramar",summary="Programar salida")public ResponseEntity<ApiResponse<FieldTripResponses.Created>>program(@Valid@RequestBody FieldTripRequests.Program q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.program(map.command(q),ids.resolve(a),meta.resolve(r)),r,FieldTripResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_EDITAR')")@Operation(operationId="salidasEditar",summary="Editar salida programada")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody FieldTripRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cancelar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_RETIRAR')")@Operation(operationId="salidasCancelar",summary="Cancelar salida")public ResponseEntity<ApiResponse<Void>>cancel(@PathVariable Long id,@Valid@RequestBody FieldTripRequests.Cancel q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.cancel(new FieldTripCommands.Cancel(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/finalizar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SALIDAS_CONFIRMAR')")@Operation(operationId="salidasFinalizar",summary="Finalizar salida")public ResponseEntity<ApiResponse<Void>>finish(@PathVariable Long id,@Valid@RequestBody FieldTripRequests.Finish q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.finish(new FieldTripCommands.Finish(id,q.fechaHoraRetornoReal(),q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
}
